fn insert_delimiter(numbers: Vec<i8>, delimiter: i8) -> Vec<i8> {
    // Handle edge cases for empty and single-element arrays
    if numbers.is_empty() {
        return Vec::new();
    }
    if numbers.len() == 1 {
        return numbers;
    }

    // Create a new vector to hold the result
    let mut result = Vec::with_capacity(2 * numbers.len() - 1);

    // Iterate through the input numbers
    for (i, &num) in numbers.iter().enumerate() {
        result.push(num); // Add the current number
        if i < numbers.len() - 1 {
            result.push(delimiter); // Add the delimiter if not the last element
        }
    }

    result
}